using ApiToolKit.Application.DTOs.Shopee.AddOnDeal;
using ApiToolKit.Application.Interfaces.Services.Shopee;
using ApiToolKit.Domain.Common;
using ApiToolKit.Domain.Interfaces.Repositories.Shopee;
namespace ApiToolKit.Application.Services.Shopee;
public class ShopeeAddOnDealService : IShopeeAddOnDealService
{
    private readonly IShopeeAuthRepository _authRepo;
    private readonly IShopeeApiClient _apiClient;
    public ShopeeAddOnDealService(IShopeeAuthRepository authRepo, IShopeeApiClient apiClient) { _authRepo = authRepo; _apiClient = apiClient; }
    private async Task<string?> GetToken(long shopId) { var t = await _authRepo.GetTokenByShopIdAsync(shopId); return t?.AccessToken; }
    public async Task<Result<AddOnDealResponse>> AddAddOnDealAsync(AddAddOnDealRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<AddOnDealResponse>.Fail("Access token not found."); var res = await _apiClient.PostAsync<AddOnDealResponse>("/api/v2/add_on_deal/add_add_on_deal", new { add_on_deal_name = r.AddOnDealName, start_time = r.StartTime, end_time = r.EndTime }, token, r.ShopId); return res == null ? Result<AddOnDealResponse>.Fail("No response.") : Result<AddOnDealResponse>.Ok(res); }
    public async Task<Result<AddOnDealResponse>> UpdateAddOnDealAsync(UpdateAddOnDealRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<AddOnDealResponse>.Fail("Access token not found."); var res = await _apiClient.PostAsync<AddOnDealResponse>("/api/v2/add_on_deal/update_add_on_deal", new { add_on_deal_id = r.AddOnDealId, add_on_deal_name = r.AddOnDealName, start_time = r.StartTime, end_time = r.EndTime }, token, r.ShopId); return res == null ? Result<AddOnDealResponse>.Fail("No response.") : Result<AddOnDealResponse>.Ok(res); }
    public async Task<Result<bool>> DeleteAddOnDealAsync(DeleteAddOnDealRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<bool>.Fail("Access token not found."); await _apiClient.PostAsync<dynamic>("/api/v2/add_on_deal/delete_add_on_deal", new { add_on_deal_id = r.AddOnDealId }, token, r.ShopId); return Result<bool>.Ok(true); }
    public async Task<Result<bool>> EndAddOnDealAsync(EndAddOnDealRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<bool>.Fail("Access token not found."); await _apiClient.PostAsync<dynamic>("/api/v2/add_on_deal/end_add_on_deal", new { add_on_deal_id = r.AddOnDealId }, token, r.ShopId); return Result<bool>.Ok(true); }
    public async Task<Result<AddOnDealResponse>> GetAddOnDealAsync(GetAddOnDealRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<AddOnDealResponse>.Fail("Access token not found."); var res = await _apiClient.GetAsync<AddOnDealResponse>("/api/v2/add_on_deal/get_add_on_deal", new Dictionary<string, string> { ["add_on_deal_id"] = r.AddOnDealId.ToString() }, token, r.ShopId); return res == null ? Result<AddOnDealResponse>.Fail("No response.") : Result<AddOnDealResponse>.Ok(res); }
    public async Task<Result<AddOnDealListResponse>> GetAddOnDealListAsync(GetAddOnDealListRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<AddOnDealListResponse>.Fail("Access token not found."); var q = new Dictionary<string, string> { ["status"] = r.Status, ["page_no"] = r.PageNo.ToString(), ["page_size"] = r.PageSize.ToString() }; var res = await _apiClient.GetAsync<AddOnDealListResponse>("/api/v2/add_on_deal/get_add_on_deal_list", q, token, r.ShopId); return res == null ? Result<AddOnDealListResponse>.Fail("No response.") : Result<AddOnDealListResponse>.Ok(res); }
    public async Task<Result<bool>> AddAddOnDealMainItemAsync(AddOnDealMainItemRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<bool>.Fail("Access token not found."); await _apiClient.PostAsync<dynamic>("/api/v2/add_on_deal/add_add_on_deal_main_item", new { add_on_deal_id = r.AddOnDealId, item_list = r.ItemList }, token, r.ShopId); return Result<bool>.Ok(true); }
    public async Task<Result<bool>> DeleteAddOnDealMainItemAsync(DeleteAddOnItemRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<bool>.Fail("Access token not found."); await _apiClient.PostAsync<dynamic>("/api/v2/add_on_deal/delete_add_on_deal_main_item", new { add_on_deal_id = r.AddOnDealId, item_id_list = r.ItemIdList }, token, r.ShopId); return Result<bool>.Ok(true); }
    public async Task<Result<bool>> UpdateAddOnDealMainItemAsync(AddOnDealMainItemRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<bool>.Fail("Access token not found."); await _apiClient.PostAsync<dynamic>("/api/v2/add_on_deal/update_add_on_deal_main_item", new { add_on_deal_id = r.AddOnDealId, item_list = r.ItemList }, token, r.ShopId); return Result<bool>.Ok(true); }
    public async Task<Result<object>> GetAddOnDealMainItemAsync(long shopId, long addOnDealId) { var token = await GetToken(shopId); if (token == null) return Result<object>.Fail("Access token not found."); var res = await _apiClient.GetAsync<object>("/api/v2/add_on_deal/get_add_on_deal_main_item", new Dictionary<string, string> { ["add_on_deal_id"] = addOnDealId.ToString() }, token, shopId); return res == null ? Result<object>.Fail("No response.") : Result<object>.Ok(res); }
    public async Task<Result<bool>> AddAddOnDealSubItemAsync(AddOnDealSubItemRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<bool>.Fail("Access token not found."); await _apiClient.PostAsync<dynamic>("/api/v2/add_on_deal/add_add_on_deal_sub_item", new { add_on_deal_id = r.AddOnDealId, item_list = r.ItemList }, token, r.ShopId); return Result<bool>.Ok(true); }
    public async Task<Result<bool>> DeleteAddOnDealSubItemAsync(DeleteAddOnItemRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<bool>.Fail("Access token not found."); await _apiClient.PostAsync<dynamic>("/api/v2/add_on_deal/delete_add_on_deal_sub_item", new { add_on_deal_id = r.AddOnDealId, item_id_list = r.ItemIdList }, token, r.ShopId); return Result<bool>.Ok(true); }
    public async Task<Result<bool>> UpdateAddOnDealSubItemAsync(UpdateAddOnSubItemRequest r) { var token = await GetToken(r.ShopId); if (token == null) return Result<bool>.Fail("Access token not found."); await _apiClient.PostAsync<dynamic>("/api/v2/add_on_deal/update_add_on_deal_sub_item", new { add_on_deal_id = r.AddOnDealId, item_list = r.ItemList }, token, r.ShopId); return Result<bool>.Ok(true); }
    public async Task<Result<object>> GetAddOnDealSubItemAsync(long shopId, long addOnDealId) { var token = await GetToken(shopId); if (token == null) return Result<object>.Fail("Access token not found."); var res = await _apiClient.GetAsync<object>("/api/v2/add_on_deal/get_add_on_deal_sub_item", new Dictionary<string, string> { ["add_on_deal_id"] = addOnDealId.ToString() }, token, shopId); return res == null ? Result<object>.Fail("No response.") : Result<object>.Ok(res); }
}
